const newItems = [];

// Usamos un loop con índice (i) para saber cuál es el item original
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Si el item tiene datos binarios
  if (item.binary) {
    // Recorremos cada adjunto
    for (const key of Object.keys(item.binary)) {
      newItems.push({
        json: item.json, 
        binary: {
          data: item.binary[key] 
        },
        // ESTA ES LA SOLUCIÓN:
        // Le decimos a n8n: "Este nuevo item pertenece al item número 'i' de la entrada"
        pairedItem: { 
          item: i 
        }
      });
    }
  }
}

return newItems;

return newItems;

const output = [];

for (const item of items) {
  // recorremos todos los binarios del item
  for (const key of Object.keys(item.binary || {})) {
    const bin = item.binary[key];
    const fileName = bin.fileName?.toLowerCase() || '';

    // detectamos PDFs por mimeType o extensión
    if (
      bin.mimeType === 'application/pdf' ||
      fileName.endsWith('.pdf')
    ) {
      output.push({
        json: { fileName: bin.fileName || 'archivo.pdf' },
        binary: { data: bin },
      });
    }
  }
}

return output;

const fecha = new Date();
const mesTexto = fecha.toLocaleString('es-CO', { month: 'long' });
const dia = fecha.getDate();
const anio = fecha.getFullYear();

return {
  json: {
    ...item.json,
    mes: mesTexto,
    dia: dia,
    anio: anio
  }
};

